def money_round(x):
    from decimal import Decimal, ROUND_HALF_UP
    d = Decimal(str(x))
    return float(d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
```

```python
def norm_phone(s):
    d = ''.join(c for c in s if c.isdigit())
    if d.startswith('8'):
        d = '7' + d[1:]
    if len(d) == 10:
        d = '7' + d
    if len(d) != 11:
        return None
    return d
```

